        // Steam app 4115450 lists these ten languages in addition to the original five.
        // Region variants have complete dictionaries; they never rely on English lookup.
        static string[] ExtendedLanguages()
        { return new[] { "zh-Hant", "fr", "de", "es-ES", "pt-BR", "it", "th", "vi", "pt-PT", "es-419" }; }

        static string ExtendedDisplayName(string language)
        {
            switch (language)
            {
                case "zh-Hant": return "繁體中文";
                case "fr": return "Français";
                case "de": return "Deutsch";
                case "es-ES": return "Español (España)";
                case "es-419": return "Español (LatAm)";
                case "pt-BR": return "Português (Brasil)";
                case "pt-PT": return "Português (PT)";
                case "it": return "Italiano";
                case "th": return "ไทย";
                case "vi": return "Tiếng Việt";
                default: return null;
            }
        }

        static string DetectExtendedCulture(CultureInfo culture)
        {
            string name = culture.Name.ToLowerInvariant();
            string language = culture.TwoLetterISOLanguageName.ToLowerInvariant();
            if (language == "zh" && (name.Contains("hant") || name == "zh-tw" || name == "zh-hk" || name == "zh-mo")) return "zh-Hant";
            if (language == "es") return name == "es" || name == "es-es" ? "es-ES" : "es-419";
            if (language == "pt") return name == "pt-pt" ? "pt-PT" : "pt-BR";
            if (new[] { "fr", "de", "it", "th", "vi" }.Contains(language)) return language;
            return null;
        }

        // Column order: Traditional Chinese, French, German, Spain Spanish,
        // Brazil Portuguese, Italian, Thai, Vietnamese.
        static void Extra(string key, params string[] values)
        {
            string[] languages = { "zh-Hant", "fr", "de", "es-ES", "pt-BR", "it", "th", "vi" };
            if (values.Length != languages.Length) throw new ArgumentException("Translation column count: " + key);
            for (int index = 0; index < languages.Length; index++) Add(languages[index], key, values[index]);
        }

